import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const bubbleVariants = cva(
  "aurora-bubble group/bubble relative flex w-fit max-w-[42ch] min-w-0 flex-col gap-1 group-data-[align=end]/message:self-end data-[align=end]:self-end data-[variant=ghost]:max-w-full",
  {
    variants: {
      variant: {
        default: "aurora-bubble--default",
        secondary: "aurora-bubble--secondary",
        muted: "aurora-bubble--muted",
        tinted: "aurora-bubble--tinted",
        outline: "aurora-bubble--outline",
        ghost: "aurora-bubble--ghost",
        destructive: "aurora-bubble--destructive",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function BubbleGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="bubble-group"
      className={cn("flex min-w-0 flex-col gap-1.5", className)}
      {...props}
    />
  )
}

function Bubble({
  variant = "default",
  align = "start",
  className,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof bubbleVariants> & { align?: "start" | "end" }) {
  return (
    <div
      data-slot="bubble"
      data-variant={variant}
      data-align={align}
      className={cn(bubbleVariants({ variant }), className)}
      {...props}
    />
  )
}

function BubbleContent({
  asChild = false,
  className,
  ...props
}: React.ComponentProps<"div"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "div"

  return (
    <Comp
      data-slot="bubble-content"
      className={cn(
        "aurora-bubble__content w-fit max-w-full min-w-0 overflow-hidden break-words",
        "group-data-[align=start]/bubble:rounded-[16px_16px_16px_6px] group-data-[align=end]/bubble:self-end group-data-[align=end]/bubble:rounded-[16px_16px_6px_16px]",
        className
      )}
      {...props}
    />
  )
}

const bubbleReactionsVariants = cva(
  "aurora-bubble__reactions absolute flex w-fit shrink-0 items-center justify-center gap-1",
  {
    variants: {
      side: {
        top: "top-0 -translate-y-3/4",
        bottom: "bottom-0 translate-y-3/4",
      },
      align: {
        start: "left-3",
        end: "right-3",
      },
    },
    defaultVariants: {
      side: "bottom",
      align: "end",
    },
  }
)

function BubbleReactions({
  side = "bottom",
  align = "end",
  className,
  ...props
}: React.ComponentProps<"div"> & {
  align?: "start" | "end"
  side?: "top" | "bottom"
}) {
  return (
    <div
      data-slot="bubble-reactions"
      data-align={align}
      data-side={side}
      className={cn(bubbleReactionsVariants({ side, align }), className)}
      {...props}
    />
  )
}

export { BubbleGroup, Bubble, BubbleContent, BubbleReactions, bubbleVariants }
